import sys
from collections import defaultdict

class UserActivityTracker:
    def __init__(self):
        self.user_activities = defaultdict(set)

    def addActivity(self, userId, activity):
        self.user_activities[userId].add(activity)

    def displayActivities(self, userId):
        if userId not in self.user_activities or not self.user_activities[userId]:
            print("No activities found.")
        else:
            sorted_activities = sorted(self.user_activities[userId])
            for activity in sorted_activities:
                print(activity)

def main():
    n = int(sys.stdin.readline().strip())
    tracker = UserActivityTracker()

    for _ in range(n):
        line = sys.stdin.readline().strip()
        if not line:
            continue
        parts = line.split()
        command = parts[0]

        if command == "ADD_ACTIVITY":
            userId = parts[1]
            activity = parts[2]
            tracker.addActivity(userId, activity)
        elif command == "DISPLAY_ACTIVITIES":
            userId = parts[1]
            tracker.displayActivities(userId)

if __name__ == "__main__":
    main()
